  static List<WormEscapeLevel> getLevelsByDifficulty(
    WormEscapeDifficulty difficulty,
  ) {
    return levels.where((l) => l.difficulty == difficulty).toList();
  }

  static int getLevelCount(WormEscapeDifficulty difficulty) {
    return getLevelsByDifficulty(difficulty).length;
  }

  static WormEscapeLevel getLevel(
    WormEscapeDifficulty difficulty,
    int levelNumber,
  ) {
    final diffLevels = getLevelsByDifficulty(difficulty);
    if (diffLevels.isEmpty) return levels.first;
    final safeNum = levelNumber.clamp(1, diffLevels.length);
    return diffLevels[safeNum - 1];
  }
}
